CREATE OR REPLACE PROCEDURE sp(
    para_Rating integer,
    para_Address text,
    para_ResID integer,
    para_StuID integer,
    para_LName text
)
LANGUAGE plpgsql
AS $$
BEGIN
    IF para_Rating < para_ResID THEN
        UPDATE "Restaurant" SET "Address" = 'A';
        DELETE FROM "Restaurant" WHERE "Rating" = 1;
        UPDATE "Restaurant" SET "Address" = 'B';
        DELETE FROM "Restaurant" WHERE "Rating" = 2;
        UPDATE "Restaurant" SET "Address" = 'C';
        DELETE FROM "Restaurant" WHERE "Rating" = 3;
        UPDATE "Student" SET "LName" = 'log_A';
        DELETE FROM "Student" WHERE "StuID" = 1;
        UPDATE "Student" SET "LName" = 'log_B';
        DELETE FROM "Student" WHERE "StuID" = 2;
        UPDATE "Student" SET "LName" = 'log_C';
        DELETE FROM "Student" WHERE "StuID" = 3;
        UPDATE "Restaurant" SET "Address" = para_Address;
        DELETE FROM "Restaurant" WHERE "Rating" = para_Rating;
        UPDATE "Student" SET "LName" = para_LName;
        DELETE FROM "Student" WHERE "StuID" = para_StuID;
        UPDATE "Restaurant" SET "Address" = 'phase2_A';
        DELETE FROM "Restaurant" WHERE "Rating" = 101;
        UPDATE "Restaurant" SET "Address" = 'phase2_B';
        DELETE FROM "Restaurant" WHERE "Rating" = 102;
        UPDATE "Student" SET "LName" = 'log_phase2_A';
        DELETE FROM "Student" WHERE "StuID" = 101;
        UPDATE "Student" SET "LName" = 'log_phase2_B';
        DELETE FROM "Student" WHERE "StuID" = 102;
        UPDATE "Restaurant" SET "Address" = 'phase2_C';
        DELETE FROM "Restaurant" WHERE "Rating" = 103;
        UPDATE "Student" SET "LName" = 'log_phase2_C';
        DELETE FROM "Student" WHERE "StuID" = 103;
        UPDATE "Restaurant" SET "Address" = 'complete' WHERE "Rating" = 999;
        UPDATE "Student" SET "LName" = 'complete_log' WHERE "StuID" = 999;
    ELSE
        UPDATE "Restaurant" SET "Address" = para_Address WHERE "Rating" = para_Rating;
        UPDATE "Student" SET "LName" = para_LName WHERE "StuID" = para_StuID;
    END IF;

    DELETE FROM "Visits_Restaurant" WHERE "ResID" IN (SELECT "ResID" FROM "Restaurant" WHERE "Rating" < para_Rating);
END;
$$;

